import * as U from '../ui.js';
import {groupStudyTasks} from '../study-groups.js';
const {db,TODAY,mount,heading,button,stat,section,sessionRow,taskRow,budgetCard,attendanceLines,icon,esc,empty}=U;
mount(()=>{let sessions=db.class_sessions.filter(s=>U.day(s.starts_at)===TODAY&&s.status!=='cancelled').sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)),tasks=db.tasks.filter(t=>!['done','cancelled'].includes(t.status)).sort((a,b)=>(a.due_at||'z').localeCompare(b.due_at||'z')),study=tasks.filter(t=>t.planned_start_at?.startsWith(TODAY)),b=U.budgetSummary(),alerts=db.courses.filter(c=>{let a=U.attendanceStats(c.id);return c.attendance_alert_enabled&&a.percent!==null&&a.percent<c.minimum_attendance_percent});return heading(U.date(TODAY,{weekday:'long',day:'numeric',month:'long',year:'numeric'}),`Your day, in focus.`,`Hey ${db.users[0].full_name.split(' ')[0]}, here’s what’s happening today.`,button('Add a task','tasks'))+`${!db.courses.length?'<div class="intro-banner new-workspace"><div><h2>Make this space yours.</h2><p>Add your first course, then build your schedule and study plan.</p></div><a class="btn" href="courses.html">Add a course →</a></div>':''}<div class="cards">${stat('Classes today',sessions.length,'Your timetable, all in one place','calendar')}${stat('Open deadlines',tasks.filter(t=>t.task_type!=='study').length,'Stay one step ahead','tasks')}${stat('Study planned',study.reduce((a,t)=>a+(Number(t.estimated_minutes)||0),0)+' <span>min</span>','Small steps, steady progress','study')}${stat('Budget remaining',U.money(b.remaining,b.budget?.currency_code),'Of '+U.money(b.budget?.spending_limit||0,b.budget?.currency_code)+' this month','wallet')}</div><div class="dashboard-grid"><div class="stack">${section('Today’s classes',sessions.map(sessionRow).join('')||empty('No classes today. Make space for something good.'),'<a class="text-link" href="schedule.html">View schedule →</a>',sessions.length+' classes on your timetable')}${section('Coming up next',tasks.slice(0,4).map(taskRow).join('')||empty('You’re all caught up.'),'<a class="text-link" href="tasks.html">All tasks →</a>')}${section('A little study, a little progress',groupStudyTasks(study,db.courses,db.tasks).map(group=>`<div class="today-study-subject"><h3>${esc(group.course?.name||'Personal study')}</h3>${group.tasks.map(taskRow).join('')}</div>`).join('')||empty('Nothing planned yet. Add a study task to make a start.'),'<a class="text-link" href="study.html">Open planner →</a>')}</div><div class="stack">${section(U.date(TODAY,{month:'long'})+' budget',budgetCard(),'<a class="text-link" href="budget.html">Details →</a>')}${section('Attendance check',`${alerts.length?`<div class="note warn" style="margin-bottom:12px">${icon('info')}<span><strong>${esc(alerts[0].course_code)} needs a little attention.</strong><br>Your attendance is below the course requirement.</span></div>`:''}${attendanceLines()}`,'<a class="text-link" href="attendance.html">View all →</a>')}${section('Campus shortcut',`<div class="note">${icon('book')}<div><strong>Not sure who to ask?</strong><br>Your saved offices, contacts, and university guides are one tap away.</div></div><a href="info.html" class="text-link" style="display:block;margin-top:16px">Explore campus info →</a>`)}</div></div>`});
